/// <summary>
/// Data contract class for CSD transfer orders creation.
/// </summary>
[DataContract]
class METCreateCSDTransferOrderContract
{
    private container csdSalesOrderList;
    private InventLocationId csdWarehouse;
    private boolean canContinueFromStagingLane;

}

Method.Source:
/// <summary>
/// Gets and sets CSD sales order list.
/// </summary>
/// <param name = "_csdSalesOrderList">CSD sales order list.</param>
/// <returns>CSD sales order list.</returns>
[DataMember, SysOperationControlVisibility(false)]
public container parmCSDSalesOrderList(container _csdSalesOrderList = csdSalesOrderList)
{
    csdSalesOrderList = _csdSalesOrderList;
    return csdSalesOrderList;
}

/// <summary>
/// Gets and sets CSD warehouse.
/// </summary>
/// <param name = "_csdWarehouse">CSD warehouse.</param>
/// <returns>CSD warehouse.</returns>
[DataMember, SysOperationControlVisibility(false)]
public InventLocationId parmCSDWarehouse(InventLocationId _csdWarehouse = csdWarehouse)
{
    csdWarehouse = _csdWarehouse;
    return csdWarehouse;
}

/// <summary>
/// Parm method to get/set can continue from staging lane flag, which indicates whether to consider conitinus use of customer staging position fetched from Warehouse.
/// </summary>
/// <param name = "_canContinueFromStagingLane">Boolean value</param>
/// <returns>Boolean true represents continuous use of staging lane, false to use exiting value from Warehouse's Customer starting position</returns>
[DataMemberAttribute, SysOperationControlVisibilityAttribute(false)]
public boolean parmContinueFromStagingLane(boolean _canContinueFromStagingLane = canContinueFromStagingLane)
{
    canContinueFromStagingLane = _canContinueFromStagingLane;
    return canContinueFromStagingLane;
}
